:- module(m__eu_cra_art14_manufacturer_reporting_fixtures, [cra_art14_manufacturer_reporting_subject/1, cra_art14_manufacturer_reporting_profile_for/2, cra_art14_manufacturer_reporting_assess/2]).
:- use_module(library(lists)).
:- use_module(library(iso_ext)).
:- use_module(library(between)).
:- use_module(library(dif)).
:- use_module(m__eu_cra_art14_manufacturer_reporting_cra_art14_manufacturer_reporting, [decide_cra_art14_manufacturer_reporting/2]).

cra_art14_manufacturer_reporting_subject(severe_by_protection_limb).
cra_art14_manufacturer_reporting_subject(severe_by_malicious_code_limb).
cra_art14_manufacturer_reporting_subject(not_severe_both_limbs_false).
cra_art14_manufacturer_reporting_subject(protection_limb_missing).
cra_art14_manufacturer_reporting_subject(malicious_code_limb_missing).
cra_art14_manufacturer_reporting_subject(protection_limb_unsure_referral).
cra_art14_manufacturer_reporting_subject(malicious_code_limb_unsure_referral).
cra_art14_manufacturer_reporting_subject(duplicate_key_problem).
cra_art14_manufacturer_reporting_subject(wrong_type_problem).
cra_art14_manufacturer_reporting_subject(unknown_key_problem).
cra_art14_manufacturer_reporting_subject(early_warning_without_undue_delay_given).
cra_art14_manufacturer_reporting_subject(early_warning_with_undue_delay).
cra_art14_manufacturer_reporting_subject(early_warning_undue_delay_unsure).
cra_art14_manufacturer_reporting_subject(notification_without_undue_delay_given).
cra_art14_manufacturer_reporting_subject(notification_with_undue_delay).
cra_art14_manufacturer_reporting_subject(notification_undue_delay_unsure).

cra_art14_manufacturer_reporting_profile_for(severe_by_protection_limb, [attribute(affects_protection_of_sensitive_or_important_data_or_functions, true)]).
cra_art14_manufacturer_reporting_profile_for(severe_by_malicious_code_limb, [attribute(affects_protection_of_sensitive_or_important_data_or_functions, false), attribute(leads_to_malicious_code_in_product_or_user_systems, true)]).
cra_art14_manufacturer_reporting_profile_for(not_severe_both_limbs_false, [attribute(affects_protection_of_sensitive_or_important_data_or_functions, false), attribute(leads_to_malicious_code_in_product_or_user_systems, false)]).
cra_art14_manufacturer_reporting_profile_for(protection_limb_missing, [attribute(leads_to_malicious_code_in_product_or_user_systems, false)]).
cra_art14_manufacturer_reporting_profile_for(malicious_code_limb_missing, [attribute(affects_protection_of_sensitive_or_important_data_or_functions, unsure)]).
cra_art14_manufacturer_reporting_profile_for(protection_limb_unsure_referral, [attribute(affects_protection_of_sensitive_or_important_data_or_functions, unsure), attribute(leads_to_malicious_code_in_product_or_user_systems, false)]).
cra_art14_manufacturer_reporting_profile_for(malicious_code_limb_unsure_referral, [attribute(affects_protection_of_sensitive_or_important_data_or_functions, false), attribute(leads_to_malicious_code_in_product_or_user_systems, unsure)]).
cra_art14_manufacturer_reporting_profile_for(duplicate_key_problem, [attribute(affects_protection_of_sensitive_or_important_data_or_functions, true), attribute(affects_protection_of_sensitive_or_important_data_or_functions, true)]).
cra_art14_manufacturer_reporting_profile_for(wrong_type_problem, [attribute(affects_protection_of_sensitive_or_important_data_or_functions, yes)]).
cra_art14_manufacturer_reporting_profile_for(unknown_key_problem, [attribute(affects_protection_of_sensitive_or_important_data_or_functions, true), attribute(product_category, router)]).
cra_art14_manufacturer_reporting_profile_for(early_warning_without_undue_delay_given, [attribute(early_warning_without_undue_delay, true)]).
cra_art14_manufacturer_reporting_profile_for(early_warning_with_undue_delay, [attribute(early_warning_without_undue_delay, false)]).
cra_art14_manufacturer_reporting_profile_for(early_warning_undue_delay_unsure, [attribute(early_warning_without_undue_delay, unsure)]).
cra_art14_manufacturer_reporting_profile_for(notification_without_undue_delay_given, [attribute(notification_without_undue_delay, true)]).
cra_art14_manufacturer_reporting_profile_for(notification_with_undue_delay, [attribute(notification_without_undue_delay, false)]).
cra_art14_manufacturer_reporting_profile_for(notification_undue_delay_unsure, [attribute(notification_without_undue_delay, unsure)]).

cra_art14_manufacturer_reporting_assess(Subject, Result) :-
    cra_art14_manufacturer_reporting_profile_for(Subject, Profile),
    decide_cra_art14_manufacturer_reporting(Profile, Result).
